const skillFamilyByAnyId = new Map<string, SystemStoryboardSkillFamily>();
const systemSkillOrderMap = new Map<string, number>();

SYSTEM_STORYBOARD_SKILL_FAMILIES.forEach((family, index) => {
  skillFamilyByAnyId.set(family.enId, family);
  skillFamilyByAnyId.set(family.zhId, family);
  systemSkillOrderMap.set(family.enId, index);
  systemSkillOrderMap.set(family.zhId, index);
});

export function isSystemStoryboardSkillId(skillId: string): boolean {
  return skillFamilyByAnyId.has(skillId);
}

export function getSystemStoryboardSkillFamily(skillId: string): SystemStoryboardSkillFamily | null {
  return skillFamilyByAnyId.get(skillId) ?? null;
}

export function getSystemStoryboardSkillArchetype(skillId: string): StoryboardArchetypeId | null {
  return skillFamilyByAnyId.get(skillId)?.familyId ?? null;
}

export function getLocalizedSystemStoryboardSkillId(skillId: string, interfaceLanguage?: InterfaceLanguage): string {
  const family = skillFamilyByAnyId.get(skillId);
  if (!family) return skillId;
  return getStoryboardTemplateLanguage(interfaceLanguage) === "zh" ? family.zhId : family.enId;
}

export function getDefaultSystemStoryboardSkillId(interfaceLanguage?: InterfaceLanguage): string {
  return getStoryboardTemplateLanguage(interfaceLanguage) === "zh" ? "storyboard-split-zh" : "storyboard-split";
}

export function getSystemStoryboardSkillSortIndex(skillId: string): number {
  return systemSkillOrderMap.get(skillId) ?? 999;
}

export function getSystemStoryboardSkillSeeds(): SystemStoryboardSkillSeed[] {
  const seeds: SystemStoryboardSkillSeed[] = [];
  for (const family of SYSTEM_STORYBOARD_SKILL_FAMILIES) {
    seeds.push({
      id: family.enId,
      familyId: family.familyId,
      locale: "en",
      name: family.enName,
      description: family.enDescription,
      content: family.enContent,
      iconId: family.iconId,
      gradientId: family.gradientId,
      accentHex: family.accentHex
    });
    seeds.push({
      id: family.zhId,
      familyId: family.familyId,
      locale: "zh",
      name: family.zhName,
      description: family.zhDescription,
      content: family.zhContent,
      iconId: family.iconId,
      gradientId: family.gradientId,
      accentHex: family.accentHex
    });
  }
  return seeds;
}

function buildMinimalCutColumns(interfaceLanguage?: InterfaceLanguage): StoryboardColumn[] {
  const base = getDefaultStoryboardColumns(interfaceLanguage);
  return base.map((col) => {
    if (col.id === "note" || col.id === "duration" || col.id === "custom-2") {
      return { ...col, visible: false };
    }
    return { ...col, visible: true };
  });
}

function buildCreatorExplainerColumns(interfaceLanguage?: InterfaceLanguage): StoryboardColumn[] {
  const isZh = getStoryboardTemplateLanguage(interfaceLanguage) === "zh";
  const base = getDefaultStoryboardColumns(interfaceLanguage).map((col) =>
    col.id === "note" || col.id === "duration" ? { ...col, visible: false } : col
  );
  const contentIdx = base.findIndex((col) => col.id === "content");
  const calloutCol: StoryboardColumn = {
    id: "custom-10",
    label: isZh ? "屏幕字卡" : "On-Screen Callout",
    type: "text",
    visible: true,
    custom: true
  };
  if (contentIdx >= 0) {
    base.splice(contentIdx + 1, 0, calloutCol);
  } else {
    base.push(calloutCol);
  }
  return base;
}

function buildProductLaunchColumns(interfaceLanguage?: InterfaceLanguage): StoryboardColumn[] {
  const isZh = getStoryboardTemplateLanguage(interfaceLanguage) === "zh";
  const base = getDefaultStoryboardColumns(interfaceLanguage).map((col) => {
    if (col.id === "duration") return { ...col, visible: true };
    if (col.id === "note") return { ...col, visible: false };
    return col;
  });
  const contentIdx = base.findIndex((col) => col.id === "content");
  const featureCol: StoryboardColumn = {
    id: "custom-11",
    label: isZh ? "演示亮点" : "Feature Focus",
    type: "text",
    visible: true,
    custom: true
  };
  if (contentIdx >= 0) {
    base.splice(contentIdx + 1, 0, featureCol);
  } else {
    base.push(featureCol);
  }
  return base;
}

