const systemTemplateSeedMap = new Map<string, SystemTemplateSeed>(
  SYSTEM_PROJECT_TEMPLATE_SEEDS.map((seed) => [seed.id, seed])
);

export function isSystemTemplateId(templateId: string): boolean {
  return systemTemplateSeedMap.has(templateId);
}

export function getSystemTemplateSeed(templateId: string): SystemTemplateSeed | null {
  return systemTemplateSeedMap.get(templateId) ?? null;
}

export function buildSystemProjectTemplate(
  seed: SystemTemplateSeed,
  interfaceLanguage?: InterfaceLanguage,
  resolveSkill?: (skillId: string) => { id: string; name: string }
): ProjectTemplate {
  const isZh = getStoryboardTemplateLanguage(interfaceLanguage) === "zh";
  const family =
    SYSTEM_STORYBOARD_SKILL_FAMILIES.find((item) => item.familyId === seed.skillFamilyId) ??
    SYSTEM_STORYBOARD_SKILL_FAMILIES[0]!;
  const targetSkillId = isZh ? family.zhId : family.enId;
  const fallbackSkillName = isZh ? family.zhName : family.enName;
  const resolved = resolveSkill ? resolveSkill(targetSkillId) : { id: targetSkillId, name: fallbackSkillName };

  return {
    id: seed.id,
    name: isZh ? seed.zhName : seed.enName,
    description: isZh ? seed.zhDescription : seed.enDescription,
    scope: "system",
    columns: ensureStoryboardPromptColumns(seed.buildColumns(interfaceLanguage), interfaceLanguage),
    storyboardSkillId: resolved.id,
    storyboardSkillName: resolved.name,
    createdAt: "",
    updatedAt: ""
  };
}

export function buildAllSystemProjectTemplates(
  interfaceLanguage?: InterfaceLanguage,
  resolveSkill?: (skillId: string) => { id: string; name: string }
): ProjectTemplate[] {
  return SYSTEM_PROJECT_TEMPLATE_SEEDS.map((seed) => buildSystemProjectTemplate(seed, interfaceLanguage, resolveSkill));
}
